from playwright.async_api import async_playwright
H='http://127.0.0.1:8010'
async def main():
 async with async_playwright() as pw:
  b=await pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);errors=[];alerts=[]
  async def login(mat):
   c=await b.new_context(viewport={'width':1280,'height':1000});await c.route('https://**/*',lambda r:r.abort());p=await c.new_page();p.on('pageerror',lambda e:errors.append(str(e)));p.on('dialog',lambda d:(alerts.append(d.message),asyncio.create_task(d.accept())));await p.goto(H+'/login');await p.locator('input[type=text]').first.fill(mat);await p.locator('input[type=password]').fill('PruebaSegura123!');await p.get_by_role('button',name='Iniciar Sesión',exact=True).click();await p.wait_for_function('window.SICIPCentral?.user');return c,p
